import { defineConfig } from 'vitest/config';

// Tests live in two places: colocated unit tests next to the modules they cover
// (src/**) and cross-module integration tests (tests/**). Both run under `npm test`.
// Rapier ships a CommonJS "main" inside an ESM package, which Node cannot load,
// so tests resolve the ES build directly; the Vite app build already picks it.
export default defineConfig({
  resolve: {
    alias: { '@dimforge/rapier3d-compat': '@dimforge/rapier3d-compat/rapier.es.js' },
  },
  test: {
    include: ['src/**/*.test.ts', 'tests/**/*.test.ts'],
    environment: 'node',
  },
});
EOF
